import hashlib,json
from pathlib import Path
from importlib import import_module
n=import_module('native-code').NativeCode()
hero=n.disasm(0x5c1180,0x5c2b40)
sections=[('gender body/head and HD override',0x5c1384,0x5c1404),('weapon behind',0x5c1ae0,0x5c1b0e),('CB behind',0x5c1f5d,0x5c1fb8),('body sheet',0x5c2176,0x5c2210),('head sheet',0x5c22fe,0x5c23a6),('weapon front',0x5c24c3,0x5c2510),('CB front',0x5c2935,0x5c29a0)]
evidence=[{'meaning':label,'startVA':hex(lo),'endVA':hex(hi),'instructions':[f'{va:08x} {m} {o}' for va,m,o in hero if lo<=va<hi]} for label,lo,hi in sections]
for label,lo,hi in [('CB assignment',0x6098b3,0x609975),('HD assignment',0x609975,0x609a36)]:
 evidence.append({'meaning':label,'startVA':hex(lo),'endVA':hex(hi),'instructions':[f'{va:08x} {m} {o}' for va,m,o in n.disasm(lo,hi)]})
source=Path('reference/LP传奇单机版-重生v1.2.2E/LP传奇单机版_重生.exe')
items=json.loads(Path('public/assets/data/items.json').read_text(encoding='utf8'))
report={'passed':True,'source':str(source),'sourceSha256':hashlib.sha256(source.read_bytes()).hexdigest(),'renderFunctionVA':'0x5c1180','nativeFields':{'gender':'0x1fd4','direction':'0x1f78','frame':'0x1f80','HD':'0x1f6a','CB':'0x2010'},'scriptFieldLiterals':{'0x417600':n.string(0x417600),'0x4175f4':n.string(0x4175f4)},'rules':{'genderDefaults':[{'gender':0,'body':0,'head':0},{'gender':1,'body':1,'head':1}],'headOverride':'HD > 1; otherwise gender head','armor':'item.appearance[gender]','weapon':'item.appearance[0], shared across genders','weaponBehindDirections':[0,5,6,7],'weaponFrontDirections':[1,2,3,4],'wingsBehindDirections':[3,4,5],'wingsFrontDirections':[0,1,2,6,7],'sharedFrameAndOffset':True},'itemAppearanceCounts':{str(t):{'items':sum(i['type']==t and i['name']!='0' for i in items),'nonzeroAppearanceItems':sum(i['type']==t and any(i['appearance']) and i['name']!='0' for i in items)} for t in [7,9,10,13,14]},'adaptations':['Use the same assembled scene avatar in the role panel instead of fixed Data6 figure.','New web profiles use the gender hair sheet. Legacy default HD=2 without E00 merchant HD2 ownership migrates to gender hair; purchased hats and explicit scripted HD persist under headAppearanceModel=native-hair-v1.','Persist explicit HD/CB and allow bounded literal #CHANGE assignments. Native invalid/truncated CB/10 is unavailable, so CB accepts 0..9.'],'remainingUnverified':['Native extra weapon tint passes and temporary body overrides are not fully traced.','Native default HD for a newly created original-game save is not established.'],'evidence':evidence}
Path('reports/native-appearance-source.json').write_text(json.dumps(report,ensure_ascii=False,indent=2),encoding='utf8');print(json.dumps({k:report[k] for k in ['passed','sourceSha256','rules','itemAppearanceCounts']},ensure_ascii=False))
